func (c *Controller) getPeerConfigs(allPeers []v1alpha1.BGPPeer) map[string]bgp.PeerConfig {
	peerConfigs := make(map[string]bgp.PeerConfig)
	c.bgpPeerPasswordsMutex.RLock()
	defer c.bgpPeerPasswordsMutex.RUnlock()
	for i := range allPeers {
		if c.enabledIPv4 && utilnet.IsIPv4String(allPeers[i].Address) ||
			c.enabledIPv6 && utilnet.IsIPv6String(allPeers[i].Address) {
			peerKey := generateBGPPeerKey(allPeers[i].Address, allPeers[i].ASN)
			bgpPeerConfig := bgp.PeerConfig{
				BGPPeer: &allPeers[i],
			}
			if password, exists := c.bgpPeerPasswords[peerKey]; exists {
				bgpPeerConfig.Password = password
			}
			peerConfigs[peerKey] = bgpPeerConfig
		}
	}
	return peerConfigs
}

